import { useState } from 'react';

const DATA = [
  {id:1,q:'What is React?',a:'A JavaScript library for building UIs.'},
  {id:2,q:'What is JSX?',a:'A syntax extension for JavaScript.'},
  {id:3,q:'What is useState?',a:'A hook to add state to function components.'}
];

export default function Accordion() {
  const [open, setOpen] = useState(null);
  return (
    <div className="accordion-wrap">
      {DATA.map(item => (
        <div className="accordion-item" key={item.id}>
          <button onClick={() => setOpen(open === item.id ? null : item.id)}>
            {item.q}
          </button>
          {open === item.id && <div className="answer">{item.a}</div>}
        </div>
      ))}
    </div>
  );
}

challenges.test_script:
