import Accordion from './UserCode';

test('answers are hidden initially', () => {
  render(<Accordion />);
  expect(screen.queryByText('A JavaScript library for building UIs.')).toBeNull();
});

test('clicking a question reveals its answer', () => {
  render(<Accordion />);
