import { useState } from 'react';

const COLS = ['Todo','In Progress','Done'];
const INIT = { Todo:['Write tests','Fix bug'], 'In Progress':['Build UI'], Done:['Setup repo'] };

export default function KanbanBoard() {
  const [board, setBoard] = useState(INIT);

  const move = (item, from) => {
    const nextCol = COLS[COLS.indexOf(from) + 1];
    if (!nextCol) return;
    setBoard(prev => ({
      ...prev,
      [from]: prev[from].filter(i => i !== item),
      [nextCol]: [...prev[nextCol], item]
    }));
  };

  return (
    <div className="board">
      {COLS.map(col => (
        <div className="col" key={col}>
          <h4>{col}</h4>
          {board[col].map(item => (
            <div className="card" key={item}>
              {item}
              {col !== 'Done' && <button onClick={() => move(item, col)}>→</button>}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

